[part="tabs"] { display: flex; gap: .25rem; border-bottom: 1px solid var(--ulvia-official-border-subtle, #e2e9e6); }
[part="tabs"] button { margin-bottom: -1px; border: 0; border-bottom: 3px solid transparent; border-radius: 0; background: transparent; }
[part="tabs"] button[aria-selected="true"] { border-bottom-color: var(--ulvia-official-primary, #176b4d); color: var(--ulvia-official-primary, #176b4d); }
[part="panel"] { display: grid; gap: var(--ulvia-official-spacing-md, 1rem); }
[part="cards"] { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 19rem), 1fr)); gap: var(--ulvia-official-spacing-md, 1rem); }
[part="cards"] ulvia-official-card code { display: block; overflow: hidden; color: var(--ulvia-official-text-muted, #687a72); font-size: .75rem; text-overflow: ellipsis; white-space: nowrap; }
[part="actions"] { justify-content: flex-start; flex-wrap: wrap; margin-top: auto; }
[part="cards"] ulvia-official-badge { margin-block-start: .75rem; text-transform: capitalize; }
[part="activity"] { display: grid; border: 1px solid var(--ulvia-official-border-subtle, #e2e9e6); border-radius: var(--ulvia-official-radius-lg, .75rem); overflow: clip; }
[part="activity-row"] { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: .9rem 1rem; background: var(--ulvia-official-background-raised, #fff); }
[part="activity-row"] + [part="activity-row"] { border-top: 1px solid var(--ulvia-official-border-subtle, #e2e9e6); }

dialog { width: min(42rem, calc(100% - 2rem)); max-height: calc(100% - 2rem); padding: 0; border: 1px solid var(--ulvia-official-border-default, #c9d5d0); border-radius: var(--ulvia-official-radius-xl, 1rem); color: inherit; background: var(--ulvia-official-background-raised, #fff); box-shadow: var(--ulvia-official-shadow-lg, 0 20px 50px rgb(20 40 32 / 18%)); }
dialog::backdrop { background: rgb(11 24 19 / 54%); backdrop-filter: blur(2px); }
[part="dialog-shell"] { display: grid; gap: 1rem; padding: 1.25rem; }
[part="dialog-shell"] header { align-items: flex-start; }
[part="dialog-shell"] label { display: grid; gap: .5rem; font-weight: 700; }
[part="dialog-shell"] footer { justify-content: flex-end; }
[data-dialog-error]:not(:empty), [data-migration-error]:not(:empty) { color: var(--ulvia-official-danger, #8a1c13); font-weight: 700; }

@container (max-width: 42rem) {
    [part="header"], [part="toolbar"] { align-items: stretch; flex-direction: column; }
    [part="summary"] { grid-template-columns: 1fr; }
    [part="tabs"] { overflow-x: auto; }
    input { width: 100%; }
}

