::slotted(input) { position: absolute; z-index: 2; inset: 0; width: 100%; height: 100%; margin: 0; appearance: none; cursor: pointer; }
[part="track"] { position: relative; display: block; width: var(--toggle-track-width); height: var(--toggle-track-height); box-sizing: border-box; border: 1px solid var(--ulvia-official-border-strong, #737985); border-radius: var(--ulvia-official-radius-full, 999px); background: var(--ulvia-official-background-subtle, #dfe4e1); box-shadow: inset 0 1px 2px rgb(23 33 30 / 18%); transition: border-color var(--ulvia-official-duration-fast, 120ms), background-color var(--ulvia-official-duration-fast, 120ms); }
[part="thumb"] { position: absolute; inset-block-start: 50%; inset-inline-start: -.1875rem; display: block; width: var(--toggle-thumb-size); height: var(--toggle-thumb-size); border: 1px solid var(--ulvia-official-border-default, #c8d1cd); border-radius: 50%; background: var(--ulvia-official-background-surface, #fff); box-shadow: 0 2px 5px rgb(23 33 30 / 22%); transform: translateY(-50%); transition: inset-inline-start var(--ulvia-official-duration-fast, 120ms), border-color var(--ulvia-official-duration-fast, 120ms), transform var(--ulvia-official-duration-fast, 120ms); }
:host([data-checked]) [part="track"] { border-color: transparent; background: var(--ulvia-official-primary, #086c55); }
:host([data-checked]) [part="thumb"] { inset-inline-start: calc(100% - var(--toggle-thumb-size) + .1875rem); border-color: color-mix(in srgb, var(--ulvia-official-primary, #086c55) 28%, var(--ulvia-official-background-surface, #fff)); }
:host(:hover:not([data-disabled])) [part="thumb"] { transform: translateY(-50%) scale(1.06); }
:host(:focus-within) [part="track"] { outline: 3px solid var(--ulvia-official-focus-ring, Highlight); outline-offset: 3px; }
:host([data-invalid]) [part="track"] { outline: 2px solid var(--ulvia-official-danger-border, #b42318); outline-offset: 2px; }
:host([data-disabled]) [part="control"] { cursor: not-allowed; opacity: .55; }
:host([data-disabled]) ::slotted(input) { cursor: not-allowed; }
:host([size="sm"]) { --toggle-hit-width: 2.75rem; --toggle-hit-height: 1.75rem; --toggle-track-width: 2.25rem; --toggle-track-height: .875rem; --toggle-thumb-size: 1.25rem; }
:host([size="lg"]) { --toggle-hit-width: 3.75rem; --toggle-hit-height: 2.5rem; --toggle-track-width: 3.125rem; --toggle-track-height: 1.25rem; --toggle-thumb-size: 1.75rem; }
